const body = $input.first().json.body || {};
const missing = ['brand_voice_guidelines','content_to_review'].filter(f => !body[f] || String(body[f]).trim() === '');
if (missing.length > 0) return [{ json: { _valid: false, _error: 'Missing required fields: ' + missing.join(', ') } }];
return [{ json: { ...body, _valid: true } }];

