const raw = $input.first().json.choices[0].message.content;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (typeof parsed.compliance_score !== 'number') throw new Error('Audit Agent: invalid schema — missing compliance_score');
return [{ json: { audit_output: parsed } }];

const raw = $input.first().json.choices[0].message.content;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!parsed.rewritten_content) throw new Error('Rewrite Agent: invalid schema — missing rewritten_content');
return [{ json: { rewrite_output: parsed } }];

const merged = $input.first().json;
return [{ json: {
  generation_run_id: $execution.id,
  company_name: $('Validate Input').first().json.company_name || 'unknown',
  content_type: $('Validate Input').first().json.content_type || 'general',
  audit_output: merged.audit_output || null,
  rewrite_output: merged.rewrite_output || null
} }];
